page.script:
odoo.define('time_chart.chart_render', function (require) {
    'use strict';
    var FormController = require('web.FormController');
    FormController.include({
        _update: function () {
            this._super.apply(this, arguments);
            if (this.modelName === 'time.chart') {
                this._renderChart();
            }
        },
        _renderChart: function () {
            var self = this;
            var lines = this.model.get(this.handle).data.line_ids.data;

            if (lines.length === 0) return;

            var timeData = lines.map(l => l.data.time);
            var powerData = lines.map(l => l.data.power);
            var resistanceData = lines.map(l => l.data.resistance);

            var ctx = document.getElementById('timeChart');
            if (ctx and window.Chart) {
                if (window.timeChartInstance) {
                    window.timeChartInstance.destroy();
                }
                window.timeChartInstance = new Chart(ctx, {
                    type: 'line',
                    data: {
                        labels: timeData,
                        datasets: [{
                            label: 'Мощность (Вт)',
                            data: powerData,
                            borderColor: 'rgb(75, 192, 192)',
                            yAxisID: 'y',
                        }, {
                            label: 'Сопротивление (Ом)',
                            data: resistanceData,
                            borderColor: 'rgb(255, 99, 132)',
                            yAxisID: 'y1',
                        }]
                    },
                    options: {
                        responsive: true,
                        interaction: {
                            mode: 'index',
                            intersect: false,
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                display: true,
                                position: 'left',
                            },
                            y1: {
                                type: 'linear',
                                display: true,
                                position: 'right',
                                grid: {
                                    drawOnChartArea: false,
                                },
                            },
                        }
                    },
                });
            }
        }
    });
});
